// GENERATED by ops/build-surge-carryover.py — do not edit by hand.
//
// Carries August Attack (Vol.6) into September Surge (Vol.7) as ALL-TIME only:
// each player's final Vol.6 total lands in prevSeriesPts["August Attack"], which
// the app adds to the all-time ranking. The Vol.7 series table starts at zero
// and is never written here — no sessions, no matches, no series points.
//
// The scoring functions below are lifted verbatim from august-attack-index.html,
// so totals match attack.urbanpadel.om exactly, including the best-3 group cap,
// 2x sessions, knockout points, streak and comeback bonuses.
//
// Idempotent. Reads August Attack, writes only September Surge.
// DRY=1 previews without writing.
require("dotenv").config({ path: "/opt/september-surge-api/.env" });
const { Pool } = require("pg");
const pool = new Pool({ connectionString: process.env.DATABASE_URL });
const DRY = process.env.DRY === "1";
const SERIES = "August Attack";
const GROUPS = ["A", "B", "C", "D"];
function getSessionGroups(session) { return GROUPS.slice(0, session?.groupCount || 4); }

const GROUP_COUNTED_GAMES = 3;

function getPlayerTeam(s, pid) { return (s.teams || []).find(t => t.p1Id === pid || t.p2Id === pid); }

function teamWon(m, tid) { if (!m || !m.winner) return false; if (m.winner === "team1") return m.team1Id === tid; if (m.winner === "team2") return m.team2Id === tid; return false; }

function teamGroupResults(session, teamId) {
  const out = [];
  (session.groupMatches || []).forEach(m => {
    if (m.team1Id !== teamId && m.team2Id !== teamId) return;
    if (!m.winner) return;
    const isT1 = m.team1Id === teamId;
    const won = teamWon(m, teamId);
    const lt = m.lossType || "tiebreak";
    out.push({
      pts: won ? 3 : (lt === "tiebreak" ? 2 : lt === "competitive" ? 1 : 0),
      w: won ? 1 : 0,
      gf: m.score ? (isT1 ? m.score.t1 : m.score.t2) : 0,
      ga: m.score ? (isT1 ? m.score.t2 : m.score.t1) : 0,
    });
  });
  const playedActual = out.length;
  out.sort((a, b) => b.pts - a.pts || (b.gf - b.ga) - (a.gf - a.ga) || b.gf - a.gf);
  return { all: out, counted: out.slice(0, GROUP_COUNTED_GAMES), playedActual };
}

function calcGroupStandings(session, group) {
  const teams = (session.teams || []).filter(t => t.group === group);
  const matchList = session.groupMatches || [];
  const rows = teams.map(team => {
    let pts = 0, wins = 0, played = 0, gf = 0, ga = 0;
    matchList.forEach(m => {
      if (m.team1Id !== team.id && m.team2Id !== team.id) return;
      if (!m.winner) return;
      played++;
      const isT1 = m.team1Id === team.id;
      if (m.score) { gf += isT1 ? m.score.t1 : m.score.t2; ga += isT1 ? m.score.t2 : m.score.t1; }
      if (teamWon(m, team.id)) { pts += 3; wins++; }
      else { const t = m.lossType || "tiebreak"; if (t === "tiebreak") pts += 2; else if (t === "competitive") pts += 1; }
    });
    return { team, pts, wins, played, gf, ga, gd: gf - ga };
  });
  const h2h = {};
  matchList.forEach(m => {
    if (!m.winner) return;
    const wid = m.winner === "team1" ? m.team1Id : m.team2Id;
    const lid = m.winner === "team1" ? m.team2Id : m.team1Id;
    if (!h2h[wid]) h2h[wid] = {};
    h2h[wid][lid] = (h2h[wid][lid] || 0) + 1;
  });
  return rows.sort((a, b) => {
    if (b.wins !== a.wins) return b.wins - a.wins;   // 1) most wins
    if (b.gd !== a.gd) return b.gd - a.gd;           // 2) game difference
    if (b.gf !== a.gf) return b.gf - a.gf;           // 3) games won
    const aH = (h2h[a.team.id]?.[b.team.id] || 0) - (h2h[b.team.id]?.[a.team.id] || 0);
    if (aH !== 0) return -aH;                        // 4) head-to-head
    return b.pts - a.pts;
  });
}

function getTopOfGroup(s, g) { const ov = s.topOfGroupOverride && s.topOfGroupOverride[g]; if (ov) return ov; const r = calcGroupStandings(s, g); return r[0]?.team?.id || null; }

function calcStreak(idxs) {
  if (!idxs?.length) return 0;
  const sorted = [...idxs].sort((a, b) => a - b);
  let total = 0, len = 0, last = null;
  for (const i of sorted) {
    if (last === null || i === last + 1) len++; else len = 1;
    last = i;
    // len=1: no bonus (first session alone doesn't count)
    // len=2: +1, len=3: +1, len=4: jackpot +3
    if (len === 2 || len === 3) total += 1;
    else if (len >= 4) total += 3;
  }
  return Math.min(total, 5);
}

function koMatchPts(match, teamId) {
  if (teamWon(match, teamId)) return 3;
  const t = match.lossType || "tiebreak";
  return t === "tiebreak" ? 2 : t === "competitive" ? 1 : 0;
}

function calcPlayerStats(pid, sessions) {
  let total = 0;
  const breakdown = { matchPts: 0, topOfGroup: 0, knockoutPts: 0, streakPts: 0, comebackPts: 0 };
  const stats = { groupWins: 0, groupPlayed: 0, sessionsPlayed: 0, qfReached: 0, qfWins: 0, sfReached: 0, sfWins: 0, finalsReached: 0, finalsWon: 0 };
  const attended = [];
  const partners = {};
  sessions.forEach((s, idx) => {
    const team = getPlayerTeam(s, pid); if (!team) return;
    stats.sessionsPlayed++;
    const partnerId = team.p1Id === pid ? team.p2Id : team.p1Id;
    partners[partnerId] = (partners[partnerId] || 0) + 1;
    // 2X Double Points (applies to everything except streak)
    const mult = s.doublePoints ? 2 : 1;
    let sessionPlayed = 0;
    // Group scoring is normalised to the group-of-4 baseline: only each team's
    // best GROUP_COUNTED_GAMES (3) results count toward series points, so a
    // 5-team group (4 matches) drops its lowest and the maximum matches a group
    // of 4. Win/played records below stay actual. Knockout and playoff matches
    // are not group matches, so they never enter this calculation.
    (s.groupMatches || []).forEach(m => {
      if (m.team1Id !== team.id && m.team2Id !== team.id) return;
      if (!m.winner) return;
      stats.groupPlayed++; sessionPlayed++;
      if (teamWon(m, team.id)) stats.groupWins++;
    });
    teamGroupResults(s, team.id).counted.forEach(r => {
      total += r.pts * mult; breakdown.matchPts += r.pts * mult;
    });
    // Only award top-of-group if team actually played matches
    if (sessionPlayed > 0 && getTopOfGroup(s, team.group) === team.id) { total += 1 * mult; breakdown.topOfGroup += 1 * mult; }
    // Only count streak if player actually played a match this session
    if (sessionPlayed > 0) {
      // Comeback bonus: +2 for returning after missing 2+ consecutive sessions
      if (attended.length > 0 && (idx - attended[attended.length - 1]) >= 3) {
        total += 2; breakdown.comebackPts += 2;
      }
      attended.push(idx);
    }
    const qfM = s.bracket?.qf?.find(m => (m.team1Id === team.id || m.team2Id === team.id) && m.winner);
    if (qfM) { stats.qfReached++; if (teamWon(qfM, team.id)) stats.qfWins++; const qp = (1 + koMatchPts(qfM, team.id)) * mult; total += qp; breakdown.knockoutPts += qp; }
    const sfM = s.bracket?.sf?.find(m => (m.team1Id === team.id || m.team2Id === team.id) && m.winner);
    if (sfM) { stats.sfReached++; if (teamWon(sfM, team.id)) stats.sfWins++; const sp = (2 + koMatchPts(sfM, team.id)) * mult; total += sp; breakdown.knockoutPts += sp; }
    const f = s.bracket?.final;
    if (f && (f.team1Id === team.id || f.team2Id === team.id) && f.winner) {
      stats.finalsReached++;
      const fp = (3 + koMatchPts(f, team.id) + (teamWon(f, team.id) ? 5 : 0)) * mult;
      total += fp; breakdown.knockoutPts += fp;
      if (teamWon(f, team.id)) stats.finalsWon++;
    }
  });
  const streak = calcStreak(attended); total += streak; breakdown.streakPts = streak;
  return { totalPts: total, breakdown, stats, attended, partners };
}

(async () => {
  const aa = (await pool.query("select data from aa_tournament_state where id=1")).rows[0]?.data;
  const ssRow = (await pool.query("select data, version from ss_tournament_state where id=1")).rows[0];
  if (!aa) throw new Error("missing aa_tournament_state");
  if (!ssRow) throw new Error("missing ss_tournament_state — is september-surge-api running?");

  const ss = ssRow.data && Object.keys(ssRow.data).length ? ssRow.data : {};
  ss.players = ss.players || [];
  ss.sessions = ss.sessions || [];

  const sessionsBefore = ss.sessions.length;
  const sessions = aa.sessions || [];
  const unfinished = sessions.filter(s => !s.completed).map(s => s.name);
  if (unfinished.length)
    console.log("NOTE: Vol.6 still has unfinished sessions:", unfinished.join(", "),
                "\n      totals are provisional — re-run this after they complete.\n");

  // Final Vol.6 totals, straight from the app's own engine.
  const finals = new Map();
  for (const p of aa.players || []) {
    const r = calcPlayerStats(p.id, sessions);
    if (r.stats.sessionsPlayed > 0) finals.set(p.id, { src: p, total: r.totalPts });
  }

  const byId = new Map(ss.players.map(p => [p.id, p]));
  let added = 0, changed = 0, same = 0;
  const changes = [];

  for (const [pid, { src, total }] of finals) {
    let dp = byId.get(pid);
    if (!dp) {
      // Carry the player across with every earlier volume they already hold,
      // so the all-time ranking stays complete rather than starting at Vol.6.
      dp = { id: src.id, name: src.name, addedAt: src.addedAt || Date.now(),
             photoUrl: src.photoUrl || "", prevSeriesPts: { ...(src.prevSeriesPts || {}) } };
      ss.players.push(dp); byId.set(pid, dp); added++;
      changes.push(["ADD", src.name, "-", total]);
      continue;
    }
    const before = (dp.prevSeriesPts || {})[SERIES];
    if (before === total) { same++; continue; }
    dp.prevSeriesPts = { ...(dp.prevSeriesPts || {}), [SERIES]: total };
    changed++;
    changes.push(["SET", dp.name, before === undefined ? "-" : before, total]);
  }
  // New arrivals get their Vol.6 total recorded too.
  for (const [pid, { total }] of finals) {
    const dp = byId.get(pid);
    if ((dp.prevSeriesPts || {})[SERIES] === undefined)
      dp.prevSeriesPts = { ...(dp.prevSeriesPts || {}), [SERIES]: total };
  }

  // Every volume Vol.6 knew about, plus Vol.6 itself.
  const names = [...(aa.prevSeriesNames || [])];
  if (!names.includes(SERIES)) names.push(SERIES);
  ss.prevSeriesNames = names;

  const aaPhotos = (await pool.query("select player_id, photo_data from aa_player_photos")).rows;
  const ssHave = new Set((await pool.query("select player_id from ss_player_photos")).rows.map(r => r.player_id));
  const toCopy = aaPhotos.filter(r => finals.has(r.player_id) && !ssHave.has(r.player_id));

  console.log("Vol.6 players with points   :", finals.size);
  console.log("Surge roster before / after :", byId.size - added, "/", byId.size);
  console.log("added / updated / unchanged :", added, "/", changed, "/", same);
  console.log("photos to copy              :", toCopy.length);
  console.log("prevSeriesNames             :", ss.prevSeriesNames.join(", "));
  console.log("\ntop 10 carried all-time totals:");
  [...finals.values()].sort((a, b) => b.total - a.total).slice(0, 10)
    .forEach((f, i) => console.log("  ", String(i + 1).padStart(2), String(f.src.name).padEnd(22), f.total));

  // A carry-over must never manufacture Vol.7 play.
  if (ss.sessions.length !== sessionsBefore)
    throw new Error("refusing: this script must not touch Vol.7 sessions");

  if (DRY) { console.log("\nDRY RUN — nothing written."); await pool.end(); return; }

  const newVersion = (ssRow.version || 0) + 1;
  await pool.query("UPDATE ss_tournament_state SET data=$1, version=$2, updated_at=NOW() WHERE id=1",
                   [ss, newVersion]);
  for (const r of toCopy)
    await pool.query(`INSERT INTO ss_player_photos (player_id, photo_data) VALUES ($1,$2)
                      ON CONFLICT (player_id) DO NOTHING`, [r.player_id, r.photo_data]);
  console.log("\nWROTE ss_tournament_state version", newVersion,
              "| players:", ss.players.length, "| sessions:", ss.sessions.length,
              "| photos copied:", toCopy.length);
  await pool.end();
})().catch(e => { console.error("FAILED:", e.message); process.exit(1); });
